nb, '[{"label":"Client''s local time (24-hour, HH:MM)","accept":["2100"]}]'::jsonb, false, 3, 200, 'Go from IST to UTC first (subtract 5 h 30 min), then add the client''s offset. Wrap past midnight.', '08:30 IST → Chicago 21:00', null, 25, 'published'), ('recovery-clock2-40', 'worldclock', 'recovery', 'World Clock', 'maths', 1, array['any']::text[], 'A client call is booked from Siruseri. Scout has the time in India, Intel knows where the client sits, Decoder has the time offsets. What time is it for the client?', '{"scout":{"title":"Call time in India (IST)","body":"15:15","big":true},"intel":{"title":"Client office","body":"The client joins from London."},"decoder":{"title":"Offsets from UTC (use exactly these)","body":"India (IST) = UTC +5:30\nLondon = UTC +0\nNew York = UTC −5\nDubai = UTC +4\nSingapore = UTC +8\nSydney = UTC +11\nFrankfurt = UTC +1\nToronto = UTC −5\nTokyo = UTC +9\nJohannesburg = UTC +2\nChicago = UTC −6"}}'::jsonb, '[{"label":"Client''s local time (24-hour, HH:MM)","accept":["0945"]}]'::jsonb, false, 5, 120, 'Go from IST to UTC first (subtract 5 h 30 min), then add the client''s offset. Wrap past midnight.', '15:15 IST → London 09:45', null, 25, 'published'), ('recovery-clock2-41', 'worldclock', 'recovery', 'World Clock', 'maths', 2, array['any']::text[], 'A client call is booked from Siruseri. Scout has the time in India, Intel knows where the client sits, Decoder has the time offsets. What time is it for the client?', '{"scout":{"title":"Call time in India (IST)","body":"21:45","big":true},"intel":{"title":"Client office","body":"The client joins from New York."},"decoder":{"title":"Offsets from UTC (use exactly these)","body":"India (IST) = UTC +5:30\nLondon = UTC +0\nNew York = UTC −5\nDubai = UTC +4\nSingapore = UTC +8\nSydney = UTC +11\nFrankfurt = UTC +1\nToronto = UTC −5\nTokyo = UTC +9\nJohannesburg = UTC +2\nChicago = UTC −6"}}'::jsonb, '[{"label":"Client''s local time (24-hour, HH:MM)","accept":["1115"]}]'::jsonb, false, 5, 120, 'G